CREATE TABLE "banned_word"
(
    "id"         int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "active"     boolean                                 NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT NULL NULL,
    "updated_at" timestamp(6) with time zone DEFAULT NULL NULL,
    "use_regex"  boolean                                 NOT NULL,
    "word"       varchar(100)                            NOT NULL
);

CREATE TABLE "curation"
(
    "id"            int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "title"         varchar(100)                            NOT NULL,
    "active"        boolean                                 NOT NULL,
    "display_count" int DEFAULT NULL NULL,
    "refresh_cycle" varchar(50)                             NOT NULL,
    "sort_type"     varchar(50) NULL,
    "visible_from"  date                                    NOT NULL,
    "visible_to"    date                                    NOT NULL,
    "created_at"    timestamp(6) with time zone             NOT NULL,
    "updated_at"    timestamp(6) with time zone NULL
);

CREATE TABLE "curation_exhibit"
(
    "id"            int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "curation_id"   int                                  NOT NULL,
    "display_order" int                                     NOT NULL,
    "exhibit_id"    int                                  NOT NULL
);

CREATE TABLE "exhibit"
(
    "id"      int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "exhibit_hall_id" int                                  NOT NULL,
    "title"           varchar(255)                DEFAULT NULL NULL,
    "description"     text NULL,
    "poster_url"      varchar(1024)               DEFAULT NULL NULL,
    "random_key"      double precision                        NOT NULL,
    "status"          varchar(50)                             NOT NULL,
    "ticket_url"      varchar(1024)               DEFAULT NULL NULL,
    "start_date"      date                        DEFAULT NULL NULL,
    "end_date"        date                        DEFAULT NULL NULL,
    "updated_at"      timestamp(6) with time zone DEFAULT NULL NULL,
    "created_at"      timestamp(6) with time zone DEFAULT NULL NULL
);

CREATE TABLE "exhibit_hall"
(
    "id"            int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name"          varchar(255)                            NOT NULL,
    "address"       varchar(255)                DEFAULT NULL NULL,
    "phone"         varchar(255)                DEFAULT NULL NULL,
    "region"        varchar(255)                            NOT NULL,
    "country_code"  varchar(2)                              NOT NULL,
    "homepage_url"  varchar(1024)               DEFAULT NULL NULL,
    "latitude"      decimal(9, 7)                           NOT NULL,
    "longitude"     decimal(10, 7)                          NOT NULL,
    "opening_hours" varchar(500)                DEFAULT NULL NULL,
    "closed_days"   varchar(255)                DEFAULT NULL NULL,
    "created_at"    timestamp(6) with time zone DEFAULT NULL NULL,
    "updated_at"    timestamp(6) with time zone DEFAULT NULL NULL
);

CREATE TABLE "exhibit_keyword"
(
    "exhibit_id" int NOT NULL,
    "keyword_id" int NOT NULL
);

CREATE TABLE "keyword"
(
    "id"   int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" varchar(255)                            NOT NULL,
    "type" varchar(50)                             NOT NULL
);

CREATE TABLE "maintenance"
(
    "id"                    int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "button_text"           varchar(50)                             NOT NULL,
    "created_at"            timestamp(6) with time zone             NOT NULL,
    "end_at"                timestamp(6) with time zone             NOT NULL,
    "force_exit"            boolean                                 NOT NULL,
    "message"               varchar(1000)                           NOT NULL,
    "refresh_after_seconds" int                                     NOT NULL,
    "start_at"              timestamp(6) with time zone             NOT NULL,
    "state"                 varchar(50)                             NOT NULL,
    "title"                 varchar(100)                            NOT NULL,
    "updated_at"            timestamp(6) with time zone             NOT NULL,
    "version"               int                                  NOT NULL
);

CREATE TABLE "notice"
(
    "id"         int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"    int                                  NOT NULL,
    "title"      varchar(255)                DEFAULT NULL NULL,
    "content"    varchar(255)                DEFAULT NULL NULL,
    "role"       varchar(50)                             NOT NULL,
    "created_at" timestamp(6) with time zone DEFAULT NULL NULL,
    "updated_at" timestamp(6) with time zone DEFAULT NULL NULL
);

CREATE TABLE "recent_exhibit"
(
    "id"         int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"    int                                  NOT NULL,
    "exhibit_id" int                                  NOT NULL,
    "viewed_at"  timestamp(6) with time zone             NOT NULL
);

CREATE TABLE "review"
(
    "id"               int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"          int                                  NOT NULL,
    "content"          varchar(500)                            NOT NULL,
    "status"           varchar(50)                             NOT NULL,
    "visit_date"       date                        DEFAULT NULL NULL,
    "exhibit_id"       int                                  NOT NULL,
    "rejected_at"      timestamp(6) with time zone DEFAULT NULL NULL,
    "rejection_reason" varchar(500)                DEFAULT NULL NULL,
    "created_at"       timestamp(6) with time zone             NOT NULL,
    "updated_at"       timestamp(6) with time zone DEFAULT NULL NULL
);

CREATE TABLE "review_image"
(
    "id"            int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "review_id"     int                                  NOT NULL,
    "display_order" int                                     NOT NULL,
    "image_url"     varchar(1024)                           NOT NULL,
    "created_at"    timestamp(6) with time zone             NOT NULL
);

CREATE TABLE "search_history"
(
    "id"         int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"    int                                  NOT NULL,
    "content"    varchar(255)                            NOT NULL,
    "created_at" timestamp(6) with time zone             NOT NULL
);

CREATE TABLE "social_accounts"
(
    "id"                     int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"                int                                  NOT NULL,
    "provider"               varchar(50)                             NOT NULL,
    "provider_user_id"       varchar(255)                            NOT NULL,
    "provider_refresh_token" text NULL,
    "linked_at"              timestamp(6) with time zone             NOT NULL
);

ALTER TABLE "social_accounts"
    ADD CONSTRAINT "PK_SOCIAL_ACCOUNTS"
        PRIMARY KEY ("id");

ALTER TABLE "social_accounts"
    ADD CONSTRAINT "UQ_SOCIAL_ACCOUNTS_PROVIDER_ACCOUNT"
        UNIQUE ("provider", "provider_user_id");

ALTER TABLE "social_accounts"
    ADD CONSTRAINT "UQ_SOCIAL_ACCOUNTS_USER_PROVIDER"
        UNIQUE ("user_id", "provider");

CREATE TABLE "user_keyword"
(
    "id"         int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"    int                                  NOT NULL,
    "keyword_id" int                                  NOT NULL,
    "created_at" timestamp(6) with time zone             NOT NULL
);

CREATE TABLE "user_notice"
(
    "id"           int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"      int                                  NOT NULL,
    "title"        varchar(255)                                     DEFAULT NULL NULL,
    "action"       varchar(50)                             NOT NULL,
    "body"         varchar(255)                                     DEFAULT NULL NULL,
    "is_read"      boolean                                 NOT NULL DEFAULT false,
    "read_at"      timestamp(6) with time zone                      DEFAULT NULL NULL,
    "reference_id" int                                           DEFAULT NULL NULL,
    "created_at"   timestamp(6) with time zone             NOT NULL
);

CREATE TABLE "users"
(
    "id"                int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name"              varchar(255)                            NOT NULL,
    "email"             varchar(255) DEFAULT NULL NULL,
    "fcm_token"         varchar(255) DEFAULT NULL NULL,
    "nickname"          varchar(255) DEFAULT NULL NULL,
    "onboarding_step"   varchar(50)                             NOT NULL,
    "profile_image_url" varchar(255) DEFAULT NULL NULL,
    "push_enabled"      boolean                                 NOT NULL,
    "role"              varchar(50)                             NOT NULL,
    "updated_at"        timestamp(6) with time zone             NOT NULL,
    "created_at"        timestamp(6) with time zone             NOT NULL
);


CREATE TABLE "favorite"
(
    "id"         int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id"    int                                  NOT NULL,
    "exhibit_id" int                                  NOT NULL,
    "created_at" timestamp(6) with time zone             NOT NULL
);


CREATE TABLE "exhibit_sync"
(
    "id"           int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "exhibit_id"   int                                  NOT NULL,
    "source"       varchar(50)                             NOT NULL,
    "external_id"  varchar(255)                            NOT NULL,
    "content_hash" char(64)                                NOT NULL,
    "synced_at"    timestamp(6) with time zone             NOT NULL
);


