ALTER TABLE "exhibit"
    ADD CONSTRAINT "CK_EXHIBIT_DATE_RANGE"
        CHECK (
            "start_date" IS NULL
                OR "end_date" IS NULL
                OR "start_date" <= "end_date"
            );

ALTER TABLE "user_notice"
    ADD CONSTRAINT "CK_USER_NOTICE_READ_STATE"
        CHECK (
            (
                "is_read" = false
                    AND "read_at" IS NULL
                )
                OR
            (
                "is_read" = true
                    AND "read_at" IS NOT NULL
                )
            );

ALTER TABLE "maintenance"
    ADD CONSTRAINT "CK_MAINTENANCE_PERIOD"
        CHECK ("start_at" < "end_at");

ALTER TABLE "maintenance"
    ADD CONSTRAINT "CK_MAINTENANCE_REFRESH_AFTER_SECONDS"
        CHECK ("refresh_after_seconds" >= 0);

ALTER TABLE "maintenance"
    ADD CONSTRAINT "CK_MAINTENANCE_VERSION"
        CHECK ("version" >= 0);

ALTER TABLE "maintenance"
    ADD CONSTRAINT "CK_MAINTENANCE_AUDIT_TIME"
        CHECK ("created_at" <= "updated_at");

ALTER TABLE "curation"
    ADD CONSTRAINT "CK_CURATION_VISIBLE_PERIOD"
        CHECK ("visible_from" <= "visible_to");

ALTER TABLE "curation"
    ADD CONSTRAINT "CK_CURATION_DISPLAY_COUNT"
        CHECK (
            "display_count" IS NULL
                OR "display_count" >= 0
            );

ALTER TABLE "curation"
    ADD CONSTRAINT "CK_CURATION_AUDIT_TIME"
        CHECK (
            "updated_at" IS NULL
                OR "created_at" <= "updated_at"
            );

ALTER TABLE "curation_exhibit"
    ADD CONSTRAINT "UQ_CURATION_EXHIBIT"
        UNIQUE ("curation_id", "exhibit_id");

ALTER TABLE "curation_exhibit"
    ADD CONSTRAINT "UQ_CURATION_EXHIBIT_DISPLAY_ORDER"
        UNIQUE ("curation_id", "display_order");

ALTER TABLE "curation_exhibit"
    ADD CONSTRAINT "CK_CURATION_EXHIBIT_DISPLAY_ORDER"
        CHECK ("display_order" >= 0);

ALTER TABLE "keyword"
    ADD CONSTRAINT "UQ_KEYWORD_TYPE_NAME"
        UNIQUE ("type", "name");

ALTER TABLE "user_keyword"
    ADD CONSTRAINT "UQ_USER_KEYWORD"
        UNIQUE ("user_id", "keyword_id");

ALTER TABLE "recent_exhibit"
    ADD CONSTRAINT "UQ_RECENT_EXHIBIT_USER_EXHIBIT"
        UNIQUE ("user_id", "exhibit_id");

CREATE INDEX "IX_RECENT_EXHIBIT_USER_VIEWED_AT"
    ON "recent_exhibit" ("user_id", "viewed_at" DESC);

ALTER TABLE "notice"
    ADD CONSTRAINT "CK_NOTICE_AUDIT_TIME"
        CHECK (
            "updated_at" IS NULL
                OR "created_at" IS NULL
                OR "created_at" <= "updated_at"
            );

ALTER TABLE "exhibit_hall"
    ADD CONSTRAINT "CK_EXHIBIT_HALL_LATITUDE"
        CHECK ("latitude" BETWEEN -90 AND 90);

ALTER TABLE "exhibit_hall"
    ADD CONSTRAINT "CK_EXHIBIT_HALL_LONGITUDE"
        CHECK ("longitude" BETWEEN -180 AND 180);


ALTER TABLE "exhibit_hall"
    ADD CONSTRAINT "CK_EXHIBIT_HALL_COUNTRY_CODE_FORMAT"
        CHECK (
            "country_code" ~ '^[A-Z]{2}$'
    );

CREATE INDEX "IX_EXHIBIT_HALL_COUNTRY_REGION"
    ON "exhibit_hall" ("country_code", "region");

CREATE INDEX "IX_FAVORITE_USER_CREATED_AT"
    ON "favorite" ("user_id", "created_at" DESC);

CREATE INDEX "IX_USER_NOTICE_USER_CREATED_AT"
    ON "user_notice" ("user_id", "created_at" DESC);

CREATE INDEX "IX_USER_NOTICE_UNREAD_USER"
    ON "user_notice" ("user_id") WHERE "is_read" = false;

CREATE INDEX "IX_REVIEW_EXHIBIT_CREATED_AT"
    ON "review" ("exhibit_id", "created_at" DESC);

CREATE INDEX "IX_REVIEW_USER_CREATED_AT"
    ON "review" ("user_id", "created_at" DESC);

CREATE INDEX "IX_EXHIBIT_KEYWORD_KEYWORD_EXHIBIT"
    ON "exhibit_keyword" ("keyword_id", "exhibit_id");

CREATE INDEX "IX_USER_KEYWORD_KEYWORD_USER"
    ON "user_keyword" ("keyword_id", "user_id");

CREATE INDEX "IX_CURATION_EXHIBIT_EXHIBIT"
    ON "curation_exhibit" ("exhibit_id");

CREATE INDEX "IX_EXHIBIT_EXHIBIT_HALL"
    ON "exhibit" ("exhibit_hall_id");

CREATE INDEX "IX_FAVORITE_EXHIBIT"
    ON "favorite" ("exhibit_id");

CREATE INDEX "IX_EXHIBIT_SYNC_EXHIBIT"
    ON "exhibit_sync" ("exhibit_id");

ALTER TABLE "review_image"
    ADD CONSTRAINT "UQ_REVIEW_IMAGE_DISPLAY_ORDER"
        UNIQUE ("review_id", "display_order");

ALTER TABLE "review_image"
    ADD CONSTRAINT "CK_REVIEW_IMAGE_DISPLAY_ORDER"
        CHECK ("display_order" >= 0);
